SELECT c.contract_id, h.CHANGE_CONTRACT_ID, c.PROJECT_ID, h.manage_number, c.contract_number, c.contract_name, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE c.tenant_id = HBM.BP_ID ) BP_NAME, h.handling_method, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'CSH1001.HANDLING_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and h.handling_method = scvb.value) handling_method_n, h.execution_result, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'CSH1001.EXECUTION_RESULT' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and h.execution_result = scvb.value) execution_result_n, (select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW') deposit_amount, decode(h.handling_method,'1',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '2',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '3',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'),decode(h.execution_result,'WRITE_OFF',(select w.due_amount from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )),(select w.due_amount - nvl(w.received_amount,0) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and w.cf_direction = 'INFLOW' and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )))) PERFORM_AMOUNT, decode(h.handling_method,'1',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '2',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '3',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'),((select sum(w.due_amount /*- nvl(w.received_amount,0)*/ ) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW') - decode(h.execution_result,'WRITE_OFF',(select w.due_amount from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )),(select w.due_amount - nvl(w.received_amount,0) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and w.cf_direction = 'INFLOW' and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 ))) )) AFTERPERFORM_BALANCE, h.creation_date as CREATE_DATE, h.manage_hd_id, h.AFTER_CHANGE_WAY, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'PRJ.MARGIN_PAYMENT_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = h.AFTER_CHANGE_WAY) AFTER_CHANGE_WAY_N, (select decode(nvl(cc.write_off_flag,'NOT'),'NOT','未核销','PARTIAL','部分核销','全部核销') from con_contract_cashflow cc where cc.cf_item = 1 AND cc.cf_status != 'BLOCK' and cc.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = cc.contract_id and w.cf_item = 1 and trunc(w.due_date) >= trunc(sysdate)) and c.contract_id = cc.contract_id and cc.cf_direction = 'INFLOW') VERIFICATION_STATE, (select s.description from sys_user s where s.user_id = h.created_by) applicant, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'PRJ.MARGIN_PAYMENT_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = c.deposit_deduction) deposit_deduction_n, (select cc.due_date from con_contract_cashflow cc where cc.cf_item = 1 AND cc.cf_status != 'BLOCK' and cc.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = cc.contract_id and w.cf_item = 1 and trunc(w.due_date) >= trunc(sysdate)) and c.contract_id = cc.contract_id and cc.cf_direction = 'INFLOW') due_date, h.description FROM con_contract c left join CSH_DEPOSIT_manage_hd h on c.contract_id = h.contract_id
1=1 and c.data_class = 'NORMAL'
and c.contract_number=#{contractNumber}
and h.manage_number = #{manageNumber}
and c.contract_name = #{contractName}
and h.handling_method = #{handlingMethod}
and h.execution_result = #{executionResult}
and trunc(h.creation_date) = trunc(#{createDate})
and ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE c.tenant_id = HBM.BP_ID ) like concat(concat('%',#{bpName}),'%')
and h.manage_hd_id=#{manageHdId}
and c.project_id = #{projectId}
and c.contract_id = #{contractId}
order by h.creation_date desc

SELECT c.contract_id, h.CHANGE_CONTRACT_ID, c.PROJECT_ID, h.manage_number, c.contract_number, c.contract_name, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE c.tenant_id = HBM.BP_ID ) BP_NAME, h.handling_method, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'CSH1001.HANDLING_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = (case when h.handling_method in('1','2','3') then '1' else '0' end)) handling_method_n, h.execution_result, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'CSH1001.EXECUTION_RESULT' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and h.execution_result = scvb.value) execution_result_n, (select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW') deposit_amount, decode(h.handling_method,'1',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '2',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '3',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'),decode(h.execution_result,'WRITE_OFF',(select w.due_amount from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )),(select w.due_amount - nvl(w.received_amount,0) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and w.cf_direction = 'INFLOW' and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )))) PERFORM_AMOUNT, decode(h.handling_method,'1',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '2',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'), '3',(select sum(w.due_amount/* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW'),((select sum(w.due_amount /* - nvl(w.received_amount,0)*/) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = 0 and w.cf_direction = 'INFLOW') - decode(h.execution_result,'WRITE_OFF',(select w.due_amount from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 )),(select w.due_amount - nvl(w.received_amount,0) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and w.cf_direction = 'INFLOW' and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 ))) )) AFTERPERFORM_BALANCE, h.creation_date as CREATE_DATE, h.manage_hd_id, h.AFTER_CHANGE_WAY, (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'PRJ.MARGIN_PAYMENT_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = h.AFTER_CHANGE_WAY) AFTER_CHANGE_WAY_N, (select decode(nvl(cc.write_off_flag,'NOT'),'NOT','未核销','PARTIAL','部分核销','全部核销') from con_contract_cashflow cc where cc.cf_item = 1 AND cc.cf_status != 'BLOCK' and cc.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = cc.contract_id and w.cf_item = 1 and trunc(w.due_date) >= trunc(sysdate)) and c.contract_id = cc.contract_id and cc.cf_direction = 'INFLOW') VERIFICATION_STATE, (select s.description from sys_user s where s.user_id = h.created_by) applicant, -- 合同已复制则变更前的保证金处理方式从复制出来的合同取(这个在审批通过后不会改变), 未复制合同的变更仍从原始合同取变更前保证金处理方式 case when h.change_contract_id is not null then (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'PRJ.MARGIN_PAYMENT_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = (select c2.deposit_deduction from con_contract c2 where c2.contract_id = h.change_contract_id)) else (Select scvb.meaning As value_name From sys_code_value_b scvb, sys_code_b scb Where scb.code = 'PRJ.MARGIN_PAYMENT_METHOD' And scb.code_id = scvb.code_id And scvb.enabled_flag = 'Y' and scvb.value = c.deposit_deduction) end as deposit_deduction_n, h.description FROM con_contract c,CSH_DEPOSIT_manage_hd h
