 = c.contract_id and w.cf_item = 1 and w.cf_direction = 'INFLOW' and w.times = (select min(cw.times) from con_contract_cashflow cw where cw.contract_id = w.contract_id and trunc(cw.due_date) >= trunc(sysdate) and cw.cf_item = 1 ) ) due_date FROM CSH_DEPOSIT_manage_hd h,con_contract c
