SELECT c.times, c.due_date, c.due_amount, c.received_amount, c.principal, c.net_principal, c.interest, --手续费 t.contract_id, c.cashflow_id, (select q.lease_charge from prj_quotation q where q.quotation_id = c.quotation_id )lease_charge, (select q.deposit from prj_quotation q where q.quotation_id = c.quotation_id )deposit,
(select q.before_rent_total from prj_quotation q where q.quotation_id = c.quotation_id )before_rent_total, (select q.down_payment from prj_quotation q where q.quotation_id = c.quotation_id )down_payment
FROM con_contract t, con_contract_cashflow c
t.contract_id = c.contract_id AND c.cf_item = 1 AND c.cf_status != 'BLOCK' AND t.data_class = 'NORMAL' /*and t.contract_status = 'INCEPT'*/ and c.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and trunc(w.due_date) >= trunc(sysdate)) and nvl(c.write_off_flag,'NOT') in('NOT','PARTIAL') and c.cf_direction = 'INFLOW'
and t.project_id = #{projectId}
and t.contract_id = #{contractId}

SELECT c.times, c.due_date, c.due_amount, c.received_amount, c.principal, c.net_principal, c.interest, --手续费 t.contract_id, c.cashflow_id, (select q.lease_charge from prj_quotation q where q.quotation_id = c.quotation_id )lease_charge, (select q.deposit from prj_quotation q where q.quotation_id = c.quotation_id )deposit,
(select q.before_rent_total from prj_quotation q where q.quotation_id = c.quotation_id )before_rent_total, (select q.down_payment from prj_quotation q where q.quotation_id = c.quotation_id )down_payment
FROM con_contract t, con_contract_cashflow c
t.contract_id = c.contract_id AND c.cf_item = 1 AND c.cf_status != 'BLOCK' AND t.data_class = 'NORMAL' and c.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 51 and w.TIMES > 0) and c.cf_direction = 'INFLOW'
and t.project_id = #{projectId}
and t.contract_id = #{contractId}

SELECT c.times, c.due_date, c.due_amount, c.received_amount, c.principal, c.net_principal, c.interest, --手续费 t.contract_id, c.cashflow_id, (select q.lease_charge from prj_quotation q where q.quotation_id = c.quotation_id )lease_charge, (select q.deposit from prj_quotation q where q.quotation_id = c.quotation_id )deposit,
(select q.before_rent_total from prj_quotation q where q.quotation_id = c.quotation_id )before_rent_total, (select q.down_payment from prj_quotation q where q.quotation_id = c.quotation_id )down_payment
FROM con_contract t, con_contract_cashflow c
t.contract_id = c.contract_id AND c.cf_item = 1 AND c.cf_status != 'BLOCK' AND t.data_class = 'NORMAL' and c.times = (select min(w.times) from con_contract_cashflow w where w.contract_id = c.contract_id and w.cf_item = 1 and trunc(w.due_date) >= trunc(sysdate)) and nvl(c.write_off_flag,'NOT') in('NOT','PARTIAL') and c.cf_direction = 'INFLOW'
and t.project_id = #{projectId}
and t.contract_id = #{contractId}
